head.b:skin:
/* Tendly - DEMO do produto (front-end, dados ficticios). Autocontido. */
/* ===== Tendly — console de atendimento (DEMO front-end, dados fictícios) ===== */
:root{
  --blue:#1875EE; --blue-d:#1564cf; --ink:#1c2024; --mute:#60646c; --faint:#8b8f98;
  --line:#e8e9ec; --line-2:#f0f1f3; --bg:#f6f7f9; --panel:#ffffff; --wa:#25d366;
  --online:#2fbf71; --away:#f0a92b; --off:#c2c6cc;
  --radius:12px; --shadow:0 1px 2px rgba(16,24,40,.04), 0 1px 3px rgba(16,24,40,.06);
}
*{box-sizing:border-box;}
html,body{margin:0;height:100%;}
body{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased;font-size:14px;line-height:1.45;}
button{font-family:inherit;cursor:pointer;}
a{color:inherit;text-decoration:none;}
svg{display:block;}
.app{display:flex;height:100vh;min-height:560px;overflow:hidden;}

/* ---------- Left rail ---------- */
.rail{width:64px;flex:none;background:#fff;border-right:1px solid var(--line);display:flex;flex-direction:column;align-items:center;padding:12px 0;gap:4px;}
.rail .logo{width:36px;height:36px;border-radius:9px;background:var(--blue);display:grid;place-items:center;color:#fff;margin-bottom:8px;}
.rail .logo svg{width:21px;height:21px;}
.rail-btn{width:42px;height:42px;border:0;background:transparent;border-radius:10px;display:grid;place-items:center;color:#8b8f98;position:relative;}
.rail-btn svg{width:21px;height:21px;}
.rail-btn:hover{background:var(--line-2);color:var(--ink);}
.rail-btn.active{background:#e9f1fe;color:var(--blue);}
.rail .spacer{flex:1;}
.rail .me{width:34px;height:34px;border-radius:50%;background:#2a3b57;color:#fff;display:grid;place-items:center;font-weight:600;font-size:12.5px;}

/* ---------- Views ---------- */
.view{flex:1;min-width:0;display:none;}
.view.active{display:flex;}

/* ---------- Inbox ---------- */
.inbox{display:flex;flex:1;min-width:0;}
.col{background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;min-width:0;}
.col-nav{width:232px;flex:none;padding:14px 10px;gap:2px;}
.col-list{width:330px;flex:none;}
.col-chat{flex:1;min-width:0;background:#f3f4f6;}
.col-contact{width:300px;flex:none;border-right:0;}

.col-nav .acct{display:flex;align-items:center;gap:8px;padding:6px 8px 12px;}
.acct .mark{width:26px;height:26px;border-radius:7px;background:var(--blue);display:grid;place-items:center;color:#fff;}
.acct .mark svg{width:15px;height:15px;}
.acct b{font-size:14px;}
.nav-group{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--faint);padding:14px 10px 6px;}
.nav-item{display:flex;align-items:center;gap:9px;padding:8px 10px;border-radius:8px;color:var(--ink);font-weight:500;}
.nav-item svg{width:17px;height:17px;color:var(--mute);}
.nav-item .count{margin-left:auto;font-size:12px;color:var(--faint);background:var(--line-2);border-radius:20px;padding:1px 8px;}
.nav-item:hover{background:var(--line-2);}
.nav-item.on{background:#e9f1fe;color:var(--blue-d);}
.nav-item.on svg{color:var(--blue);}
.dot{width:9px;height:9px;border-radius:50%;flex:none;}
.dot.cml{background:#8b5cf6;} .dot.fin{background:#f0a92b;} .dot.sup{background:#2fbf71;}

/* list header */
.list-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px 10px;border-bottom:1px solid var(--line);}
.list-head h2{margin:0;font-size:16px;font-weight:700;}
.list-head .tabs{display:flex;gap:4px;padding:8px 12px 0;}
.pill{font-size:12.5px;font-weight:600;color:var(--mute);padding:6px 10px;border-radius:7px;}
.pill.on{background:var(--line-2);color:var(--ink);}
.search{margin:10px 12px;display:flex;align-items:center;gap:8px;background:var(--line-2);border-radius:9px;padding:8px 10px;color:var(--faint);}
.search svg{width:15px;height:15px;}
.search input{border:0;background:transparent;outline:0;font-size:13px;color:var(--ink);width:100%;}

.ltabs{display:flex;gap:4px;padding:6px 12px 0;border-bottom:1px solid var(--line);}
.ltabs .pill{font-size:12.5px;font-weight:600;color:var(--mute);padding:8px 10px;border-bottom:2px solid transparent;margin-bottom:-1px;}
.ltabs .pill.on{color:var(--blue);border-bottom-color:var(--blue);}
.list-tools{display:flex;align-items:center;gap:6px;}
.iconbtn{width:32px;height:32px;border:1px solid var(--line);background:#fff;border-radius:8px;display:grid;place-items:center;color:var(--mute);}
.iconbtn svg{width:16px;height:16px;}
.iconbtn:hover{background:var(--line-2);color:var(--ink);}
.status-pill{font-size:12px;font-weight:600;color:#1a8a4e;background:#e3f6ec;border-radius:20px;padding:3px 10px;display:inline-flex;align-items:center;gap:6px;}
.status-pill .d{width:7px;height:7px;border-radius:50%;background:var(--online);}
.cp-row.pick{cursor:pointer;}
.cp-row.pick b{display:inline-flex;align-items:center;gap:6px;}
.cp-row.pick b svg{width:14px;height:14px;color:var(--faint);}
.conv{display:flex;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line-2);cursor:pointer;position:relative;}
.conv:hover{background:#fafbfc;}
.conv.sel{background:#e9f1fe;}
.conv.sel::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--blue);}
.ava{width:40px;height:40px;border-radius:50%;flex:none;display:grid;place-items:center;color:#fff;font-weight:600;font-size:14px;position:relative;}
.ava .wa{position:absolute;right:-2px;bottom:-2px;width:16px;height:16px;border-radius:50%;background:var(--wa);border:2px solid #fff;display:grid;place-items:center;}
.ava .wa svg{width:9px;height:9px;color:#fff;}
.conv .body{flex:1;min-width:0;}
.conv .row1{display:flex;align-items:center;justify-content:space-between;gap:8px;}
.conv .name{font-weight:600;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.conv .time{font-size:11.5px;color:var(--faint);flex:none;}
.conv .last{color:var(--mute);font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;}
.conv .row3{display:flex;align-items:center;gap:6px;margin-top:6px;}
.tag{font-size:11px;font-weight:600;padding:2px 8px;border-radius:20px;display:inline-flex;align-items:center;gap:5px;}
.tag.cml{background:#f1ecfe;color:#7c3aed;} .tag.fin{background:#fdf1dd;color:#b7791f;} .tag.sup{background:#e3f6ec;color:#1a8a4e;}
.badge{margin-left:auto;background:var(--wa);color:#fff;font-size:11px;font-weight:700;border-radius:20px;min-width:18px;height:18px;padding:0 5px;display:grid;place-items:center;}

/* chat */
.chat-head{display:flex;align-items:center;gap:12px;padding:12px 18px;background:var(--panel);border-bottom:1px solid var(--line);}
.chat-head>div{min-width:0;}
.chat-head .name{font-weight:700;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.chat-head .sub{font-size:12.5px;color:var(--mute);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.chat-head .actions{margin-left:auto;display:flex;gap:8px;}
.btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:8px;padding:8px 13px;font-size:13px;font-weight:600;display:inline-flex;align-items:center;gap:6px;}
.btn svg{width:15px;height:15px;}
.btn.primary{background:var(--blue);border-color:var(--blue);color:#fff;}
.btn.ok{background:#e3f6ec;border-color:#bfe8cf;color:#1a8a4e;}
.thread{flex:1;overflow:auto;padding:22px 26px;display:flex;flex-direction:column;gap:10px;background-image:radial-gradient(circle,rgba(16,24,40,.04) 1px,transparent 1px);background-size:18px 18px;}
.day{align-self:center;background:#e7eaee;color:var(--mute);font-size:11.5px;font-weight:600;padding:3px 12px;border-radius:20px;margin:4px 0;}
.msg{max-width:74%;padding:9px 13px;border-radius:14px;font-size:14px;box-shadow:var(--shadow);position:relative;}
.msg .t{font-size:10.5px;color:var(--faint);margin-top:4px;text-align:right;}
.msg.in{align-self:flex-start;background:#fff;border-bottom-left-radius:4px;}
.msg.out{align-self:flex-end;background:#d8f3e0;border-bottom-right-radius:4px;}
.composer{background:var(--panel);border-top:1px solid var(--line);padding:12px 18px;display:flex;align-items:center;gap:10px;}
.composer .field{flex:1;background:var(--line-2);border-radius:10px;padding:11px 14px;color:var(--faint);font-size:14px;}
.composer .send{width:42px;height:42px;border-radius:10px;background:var(--blue);color:#fff;border:0;display:grid;place-items:center;}
.composer .send svg{width:18px;height:18px;}

/* contact panel */
.col-contact{padding:0;}
.cp-head{padding:22px 18px 16px;text-align:center;border-bottom:1px solid var(--line);}
.cp-head .ava{width:60px;height:60px;margin:0 auto 10px;font-size:20px;}
.cp-head .nm{font-weight:700;font-size:16px;}
.cp-head .ph{color:var(--mute);font-size:13px;margin-top:2px;}
.cp-sec{padding:16px 18px;border-bottom:1px solid var(--line);}
.cp-sec h4{margin:0 0 10px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--faint);}
.cp-row{display:flex;align-items:center;justify-content:space-between;padding:6px 0;font-size:13.5px;}
.cp-row span{color:var(--mute);}
.cp-row b{font-weight:600;}

/* ---------- Generic management page ---------- */
.page{flex:1;min-width:0;display:flex;flex-direction:column;background:var(--bg);}
.page-head{background:var(--panel);border-bottom:1px solid var(--line);padding:20px 28px;}
.page-head h1{margin:0;font-size:22px;font-weight:700;letter-spacing:-.01em;}
.page-head p{margin:4px 0 0;color:var(--mute);font-size:14px;}
.page-body{padding:24px 28px;overflow:auto;}
.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:12px;flex-wrap:wrap;}
.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);}
table{width:100%;border-collapse:collapse;}
thead th{text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--faint);font-weight:600;padding:12px 18px;border-bottom:1px solid var(--line);}
tbody td{padding:14px 18px;border-bottom:1px solid var(--line-2);font-size:14px;vertical-align:middle;}
tbody tr:last-child td{border-bottom:0;}
tbody tr:hover{background:#fafbfc;}
.u{display:flex;align-items:center;gap:11px;}
.u .em{color:var(--mute);font-size:12.5px;}
.chip{font-size:12px;font-weight:600;padding:3px 10px;border-radius:20px;display:inline-flex;align-items:center;gap:6px;}
.chip.admin{background:#e9f1fe;color:var(--blue-d);} .chip.agent{background:var(--line-2);color:var(--mute);}
.st{display:inline-flex;align-items:center;gap:7px;font-size:13px;font-weight:600;}
.st .d{width:8px;height:8px;border-radius:50%;}
.st.on .d{background:var(--online);} .st.on{color:#1a8a4e;}
.st.aw .d{background:var(--away);} .st.aw{color:#b7791f;}
.st.of .d{background:var(--off);} .st.of{color:var(--faint);}

.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px;}
.scard{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:18px;}
.scard .top{display:flex;align-items:center;gap:12px;margin-bottom:12px;}
.scard .ic{width:42px;height:42px;border-radius:10px;display:grid;place-items:center;color:#fff;flex:none;}
.scard h3{margin:0;font-size:16px;font-weight:700;}
.scard .desc{color:var(--mute);font-size:13.5px;margin:0 0 14px;}
.scard .foot{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line-2);padding-top:12px;font-size:13px;color:var(--mute);}

.conn{display:flex;align-items:center;gap:14px;padding:16px 18px;border-bottom:1px solid var(--line-2);}
.conn:last-child{border-bottom:0;}
.conn .ic{width:44px;height:44px;border-radius:11px;background:#e3f6ec;display:grid;place-items:center;color:var(--wa);flex:none;}
.conn .ic svg{width:24px;height:24px;}
.conn .meta{flex:1;min-width:0;}
.conn .meta b{font-size:14.5px;font-weight:600;}
.conn .meta .num{color:var(--mute);font-size:13px;margin-top:2px;}
.conn .kind{font-size:12px;font-weight:600;color:var(--mute);background:var(--line-2);border-radius:20px;padding:3px 10px;}

@media(max-width:1100px){.col-contact{display:none;}}
@media(max-width:860px){.col-nav{display:none;}}
/* esconde a area de posts do Blogger (demo nao usa posts) */
.tendly-blogpart{display:none !important;}

body.script:
/**/
(function(){
  var rail = document.querySelectorAll(".rail-btn");
  var views = document.querySelectorAll(".view");
  function show(name){
    rail.forEach(function(b){ b.classList.toggle("active", b.getAttribute("data-view") === name); });
    views.forEach(function(v){ v.classList.toggle("active", v.id === "view-" + name); });
  }
  rail.forEach(function(b){
    b.addEventListener("click", function(){ show(b.getAttribute("data-view")); });
  });
})();
/**/
